<div class="form-group m-form__group @has_error($name)">    <label for="{{$name}}">        <i class="fa fa-{{$icon ?? 'cogs'}}"></i> <!-- Add the icon here, e.g., fa-cogs, fa-globe, etc. -->        {{ $text }}    </label>    <div class="input-group">        <select name="{{$name}}" id="{{$name}}" {{ isset($not_req) ? '' : 'required' }} class="form-control" data-search="true" {{isset($disabled) && $disabled==true ? ' disabled="disabled"':''}}>        @if(!isset($no_def))                <option value="">{{ isset($placeholder) ? $placeholder : $text }}</option>            @endif            @foreach($select as $k => $s)                <option value="{{$k}}" {{ old($name, isset($data) ? $data : null) == $k ? 'selected' : '' }}>{{ $s }}</option>            @endforeach        </select>        <div class="input-group-append">            <span class="input-group-text">                <i class="fa fa-chevron-down"></i> <!-- Dropdown arrow icon -->            </span>        </div>    </div>    @show_error($name)</div>